package com.savewhy.app;
final class Palettes {
static final int[] STYLES={R.style.PalettePowder,R.style.PaletteAmber,R.style.PaletteRed,R.style.PaletteLavender,R.style.PaletteBlue,R.style.PaletteGraphite};
static final int[] KEYS={R.color.app_background,R.color.app_surface,R.color.app_surface_soft,R.color.app_text,R.color.app_muted,R.color.app_primary,R.color.app_on_primary,R.color.app_border,R.color.app_error};
static final int[][] COLORS={{R.color.palette_powder_background,R.color.palette_powder_surface,R.color.palette_powder_surface_soft,R.color.palette_powder_text,R.color.palette_powder_muted,R.color.palette_powder_primary,R.color.palette_powder_on_primary,R.color.palette_powder_border,R.color.palette_powder_error},{R.color.palette_amber_background,R.color.palette_amber_surface,R.color.palette_amber_surface_soft,R.color.palette_amber_text,R.color.palette_amber_muted,R.color.palette_amber_primary,R.color.palette_amber_on_primary,R.color.palette_amber_border,R.color.palette_amber_error},{R.color.palette_red_background,R.color.palette_red_surface,R.color.palette_red_surface_soft,R.color.palette_red_text,R.color.palette_red_muted,R.color.palette_red_primary,R.color.palette_red_on_primary,R.color.palette_red_border,R.color.palette_red_error},{R.color.palette_lavender_background,R.color.palette_lavender_surface,R.color.palette_lavender_surface_soft,R.color.palette_lavender_text,R.color.palette_lavender_muted,R.color.palette_lavender_primary,R.color.palette_lavender_on_primary,R.color.palette_lavender_border,R.color.palette_lavender_error},{R.color.palette_blue_background,R.color.palette_blue_surface,R.color.palette_blue_surface_soft,R.color.palette_blue_text,R.color.palette_blue_muted,R.color.palette_blue_primary,R.color.palette_blue_on_primary,R.color.palette_blue_border,R.color.palette_blue_error},{R.color.palette_graphite_background,R.color.palette_graphite_surface,R.color.palette_graphite_surface_soft,R.color.palette_graphite_text,R.color.palette_graphite_muted,R.color.palette_graphite_primary,R.color.palette_graphite_on_primary,R.color.palette_graphite_border,R.color.palette_graphite_error}};
static int index(android.content.Context c){int i=c.getSharedPreferences("settings",0).getInt("palette",0);return i>=0&&i<STYLES.length?i:0;}
static int color(android.content.Context c,int id){for(int i=0;i<KEYS.length;i++)if(KEYS[i]==id)return androidx.core.content.ContextCompat.getColor(c,COLORS[index(c)][i]);return androidx.core.content.ContextCompat.getColor(c,id);}
}
